package com.loopers.interfaces.consumer;
import org.apache.kafka.clients.consumer.KafkaConsumer;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.assertj.core.api.Assertions.assertThat;
class KafkaPartitionExperimentTest{@Test void rangeAssignorHasStableTwoPartitionThreeConsumerAssignment()throws Exception{try(KafkaExperimentSupport k=new KafkaExperimentSupport();KafkaConsumer<String,String>a=k.consumer("w6-assign","A");KafkaConsumer<String,String>b=k.consumer("w6-assign","B");KafkaConsumer<String,String>c=k.consumer("w6-assign","C");ExecutorService pool=Executors.newFixedThreadPool(3)){k.topic("orders-w6",2);a.subscribe(List.of("orders-w6"));a.poll(Duration.ofSeconds(4));b.subscribe(List.of("orders-w6"));b.poll(Duration.ofSeconds(4));c.subscribe(List.of("orders-w6"));AtomicBoolean stop=new AtomicBoolean();AtomicReference<List<Integer>>aa=new AtomicReference<>(List.of()),bb=new AtomicReference<>(List.of()),cc=new AtomicReference<>(List.of());Future<?>fa=pool.submit(()->poll(a,aa,stop)),fb=pool.submit(()->poll(b,bb,stop)),fc=pool.submit(()->poll(c,cc,stop));int stable=0;for(int i=0;i<200&&stable<3;i++){Thread.sleep(100);stable=aa.get().equals(List.of(0))&&bb.get().equals(List.of(1))&&cc.get().isEmpty()?stable+1:0;}stop.set(true);fa.get(5,TimeUnit.SECONDS);fb.get(5,TimeUnit.SECONDS);fc.get(5,TimeUnit.SECONDS);assertThat(aa.get()).containsExactly(0);assertThat(bb.get()).containsExactly(1);assertThat(cc.get()).isEmpty();}}private static void poll(KafkaConsumer<String,String>c,AtomicReference<List<Integer>>a,AtomicBoolean stop){while(!stop.get()){c.poll(Duration.ofMillis(100));a.set(c.assignment().stream().map(x->x.partition()).sorted().toList());}}}
